import{_ as s,C as o,c as n,o as i,a3 as a,G as r}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Tags and degrees","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/setup/tags-degrees.md","filePath":"master/human-resources/recruitment/setup/tags-degrees.md","lastUpdated":1792041590000}'),l={name:"master/human-resources/recruitment/setup/tags-degrees.md"};function g(d,e,c,h,u,p){const t=o("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=a('<h1 id="tags-and-degrees" tabindex="-1">Tags and degrees <a class="header-anchor" href="#tags-and-degrees" aria-label="Permalink to &quot;Tags and degrees&quot;">​</a></h1><p>Tags and degrees add detail to your applicants. A tag is a coloured label, such as Warehouse Management, that helps you group and find people. A degree records the education level of a person. Both come from lists that you maintain once.</p><blockquote><p><strong>In simple words:</strong> Tags are coloured labels for applicants. Degrees are education levels you pick from a list.</p></blockquote><p>Open <code>Recruitments → Configuration → Tags</code> or <code>Recruitments → Configuration → Degrees</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>None. Both lists come with sample data.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>These tags are for applicants and candidates. Employee tags are a separate list.</p></div><h2 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>The list shows the columns <strong>Name</strong> and <strong>Color</strong>. The color appears as a small swatch. Sample tags include <strong>Sales</strong>, <strong>Manager</strong>, <strong>IT</strong>, <strong>HR</strong>, <strong>Warehouse Management</strong> and <strong>Project Management</strong>.</p>',9)),r(t,{src:"/images1/recruitment/set_tags_list.png",alt:"Tags list with the Name column and Color swatches"}),e[1]||(e[1]=a('<h3 id="create-a-tag" tabindex="-1">Create a tag <a class="header-anchor" href="#create-a-tag" aria-label="Permalink to &quot;Create a tag&quot;">​</a></h3><ol><li>Open <code>Recruitments → Configuration → Tags</code>.</li><li>Click <strong>New Tag</strong>. A <strong>Create Tags</strong> window opens.</li><li>Type <strong>Warehouse Supervisor</strong> in <strong>Name</strong>.</li><li>Pick a color in <strong>Color</strong>.</li><li>Click <strong>Create</strong>.</li></ol>',2)),r(t,{src:"/images1/recruitment/set_tag_create.png",alt:"Create Tags window with the name Warehouse Supervisor and a color chosen"}),e[2]||(e[2]=a('<ul><li><strong><em>Name:</em></strong> (required) the label text.</li><li><strong><em>Color:</em></strong> (required) pick a color with the picker. It has no default.</li></ul><h3 id="where-tags-are-used" tabindex="-1">Where tags are used <a class="header-anchor" href="#where-tags-are-used" aria-label="Permalink to &quot;Where tags are used&quot;">​</a></h3><p>You choose tags in the <strong>Tags</strong> field of the applicant form. A candidate has tags too. When an applicant has none, it shows the tags of its candidate.</p><h2 id="degrees" tabindex="-1">Degrees <a class="header-anchor" href="#degrees" aria-label="Permalink to &quot;Degrees&quot;">​</a></h2><h3 id="overview-1" tabindex="-1">Overview <a class="header-anchor" href="#overview-1" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>The list has one column, <strong>Name</strong>. The sample data holds 24 degrees, for example <strong>Chartered Accountant (CA)</strong> and degrees in human resources and finance. Use the page controls to see all of them. Degrees such as <strong>Bachelor</strong> and <strong>Master</strong> are on later pages.</p>',6)),r(t,{src:"/images1/recruitment/set_degrees_list.png",alt:"Degrees list with the Name column"}),e[3]||(e[3]=a('<h3 id="create-a-degree" tabindex="-1">Create a degree <a class="header-anchor" href="#create-a-degree" aria-label="Permalink to &quot;Create a degree&quot;">​</a></h3><ol><li>Open <code>Recruitments → Configuration → Degrees</code>.</li><li>Click <strong>New Degrees</strong>. A <strong>Create Degrees</strong> window opens.</li><li>Type a name, for example <strong>Diploma in Logistics</strong>.</li><li>Click <strong>Create</strong>.</li></ol>',2)),r(t,{src:"/images1/recruitment/set_degree_create.png",alt:"Create Degrees window with the name Diploma in Logistics"}),e[4]||(e[4]=a('<ul><li><strong><em>Name:</em></strong> (required) the degree as people will read it.</li></ul><h3 id="where-degrees-are-used" tabindex="-1">Where degrees are used <a class="header-anchor" href="#where-degrees-are-used" aria-label="Permalink to &quot;Where degrees are used&quot;">​</a></h3><p>The <strong>Degree</strong> field sits in the <strong>Education &amp; Availability</strong> section of the applicant form. It is saved on the candidate too.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../applicants/add-applicant.html">Add an applicant</a></li><li><a href="./../applicants/candidates.html">Candidates</a></li><li><a href="./sources-and-mediums.html">Sources and mediums</a></li><li><a href="./">Setup overview</a></li></ul>',5))])}const T=s(l,[["render",g]]);export{_ as __pageData,T as default};
